)

layer_norm_cpp = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void ln_reduce_kernel(const float *x, float *sumx, float *sumx2, int64_t num_rows, int64_t ld) {
  int row = blockIdx.x;
  if (row >= num_rows) return;
  extern __shared__ float sdata[];
  float *s_sum = sdata;
  float *s_sumsq = sdata + blockDim.x;
  int tid = threadIdx.x;
  float lsum = 0.0f;
  float lsumsq = 0.0f;
  for (int i = tid; i < ld; i += blockDim.x) {
    float val = x[row * ld + i];
    lsum += val;
    lsumsq += val * val;
  }
  s_sum[tid] = lsum;
  s_sumsq[tid] = lsumsq;
  __syncthreads();
  for (int s = blockDim.x / 2; s > 0; s >>= 1) {
    if (tid < s) {
      s_sum[tid] += s_sum[tid + s];
      s_sumsq[tid] += s_sumsq[tid + s];
    }
    __syncthreads();
  }
  if (tid == 0) {
    sumx[row] = s_sum[0];
    sumx2[row] = s_sumsq[0];
  }
}

__global__ void ln_apply_kernel(const float *x, float *out, const float *mean, const float *invvar,
                                 const float *gamma, const float *beta, int64_t num_rows, int64_t ld) {
  int idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx >= num_rows * ld) return;
  int row = idx / ld;
  int col = idx % ld;
  float xi = x[idx];
  out[idx] = (xi - mean[row]) * invvar[row] * gamma[col] + beta[col];
}

torch::Tensor layer_norm_hip(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta) {
  auto out = torch::empty_like(x);
  int64_t B = x.size(0);
  int64_t T = x.size(1);
  int64_t C = gamma.numel();
  int64_t num_rows = B * T;
  int64_t ld = C;
  auto sumx = torch::zeros({num_rows}, x.options());
  auto sumsq = torch::zeros({num_rows}, x.options());
  const int bs = 256;
  int grid_reduce = num_rows;
  size_t shmem = sizeof(float) * 2 * bs;
  ln_reduce_kernel<<<grid_reduce, bs, shmem>>>(x.data_ptr<float>(), sumx.data_ptr<float>(), sumsq.data_ptr<float>(), num_rows, ld);
  auto means = sumx / static_cast<float>(C);
  auto vars = sumsq / static_cast<float>(C) - torch::square(means);
  auto inv_vars = torch::rsqrt(vars + 1e-5f);
  int64_t total = num_rows * ld;
  int grid_apply = (total + bs - 1) / bs;
  ln_apply_kernel<<<grid_apply, bs>>>(x.data_ptr<float>(), out.data_ptr<float>(), means.data_ptr<float>(),
                                      inv_vars.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
                                      num_rows, ld);
  return out;
}
"""

