__global__ void causal_attention_kernel(const float* q, const float* k, const float* v, float* y, int B, int nh, int T, int hs, float scale) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * nh * T) return;

    int b = idx / (nh * T);
    int h_offset = idx % (nh * T);
    int h = h_offset / T;
    int i = h_offset % T;

    size_t off_bh = (size_t(b * nh + h)) * T * hs;
    size_t qoff = off_bh + (size_t)i * hs;

    // First pass: compute m, s
    float m = -INFINITY;
    float s = 0.0f;
    for (int j = 0; j <= i; ++j) {
        size_t koff = off_bh + (size_t)j * hs;
        float dot = 0.0f;
#pragma unroll 4
        for (int d = 0; d < hs; ++d) {
            dot += q[qoff + d] * k[koff + d];
        }
        dot *= scale;
        float m_new = fmaxf(m, dot);
        s *= expf(m - m_new);
        s += expf(dot - m_new);
        m = m_new;
    }

    // Second pass: compute y
    for (int d = 0; d < hs; ++d) {
        float sum_d = 0.0f;
        for (int j = 0; j <= i; ++j) {
            size_t koff = off_bh + (size_t)j * hs;
            float dot = 0.0f;
#pragma unroll 4
            for (int dd = 0; dd < hs; ++dd) {
                dot += q[qoff + dd] * k[koff + dd];
            }
            dot *= scale;
            float w = (s > 1e-8f) ? expf(dot - m) / s : 0.0f;
            sum_d += w * v[koff + d];
        }
        y[qoff + d] = sum_d;
    }
}

